package io.github.ningpp.compat;

/**
 * Replacement for System.Runtime.Serialization.IDeserializationCallback
 * (generated by CSharpToJava converter).
 *
 * <p>Implemented by collection types that need to run fix-up logic after their
 * state has been restored by a deserializer.</p>
 */
public interface IDeserializationCallback {

    /**
     * Runs when the entire object graph has been deserialized.
     *
     * @param sender The object that initiated the callback.
     */
    void onDeserialization(Object sender);
}
